<?php

declare(strict_types=1);

namespace Tests\Unit\Resources;

use App\Application\DTOs\ThemeSettingsDTO;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;

/**
 * The site serves the families the theme settings offer itself (core#557): resources/css/fonts.css,
 * generated by scripts/generate-fonts-css.mjs, must keep up with ThemeSettingsDTO.
 */
final class SiteFontsStylesheetTest extends TestCase
{
    private const array WEIGHTS = [400, 500, 600, 700];

    public function test_app_css_imports_the_fonts(): void
    {
        $this->assertStringContainsString("@import './fonts.css';", $this->read('resources/css/app.css'));
    }

    /**
     * @return iterable<string, array{string}>
     */
    public static function offeredFamilies(): iterable
    {
        $families = array_unique([...ThemeSettingsDTO::BODY_FONTS, ...ThemeSettingsDTO::HEADING_FONTS]);
        foreach ($families as $family) {
            if ($family !== ThemeSettingsDTO::SYSTEM_FONT) {
                yield $family => [$family];
            }
        }
    }

    #[DataProvider('offeredFamilies')]
    public function test_every_offered_family_is_declared_in_every_weight_for_latin_and_latin_ext(string $family): void
    {
        $faces = $this->faces();

        foreach (self::WEIGHTS as $weight) {
            $ranges = $faces[$family][$weight] ?? [];
            $this->assertCount(2, $ranges, "{$family} {$weight}: one face for latin-ext and one for latin");
            // latin last, so it wins for the characters both ranges cover
            $this->assertStringStartsWith('U+0000-00FF', $ranges[1]);
        }
    }

    public function test_the_files_come_from_the_site_build_never_from_a_font_service(): void
    {
        $css = $this->read('resources/css/fonts.css');

        preg_match_all("/src: url\('([^']+)'\) format\('woff2'\);/", $css, $sources);
        $this->assertSame(substr_count($css, '@font-face'), count($sources[1]));
        foreach ($sources[1] as $source) {
            $this->assertStringStartsWith('../../node_modules/@fontsource/', $source);
        }
        $this->assertStringNotContainsString('http', $css);
    }

    /**
     * @return array<string, array<int, list<string>>> family => weight => unicode ranges, in declaration order
     */
    private function faces(): array
    {
        preg_match_all(
            "/@font-face \{\s*font-family: '([^']+)';\s*font-style: normal;\s*font-display: swap;\s*font-weight: (\d+);\s*src: [^;]+;\s*unicode-range: ([^;]+);\s*\}/",
            $this->read('resources/css/fonts.css'),
            $matches,
            PREG_SET_ORDER,
        );

        $faces = [];
        foreach ($matches as [, $family, $weight, $range]) {
            $faces[$family][(int) $weight][] = $range;
        }

        return $faces;
    }

    private function read(string $path): string
    {
        $contents = file_get_contents(dirname(__DIR__, 3).'/'.$path);
        $this->assertIsString($contents);

        return $contents;
    }
}
